t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Dartol's Rod"] = "Жезл Дартола",
		["Insane druids"] = "Обезумевшие друиды",
		["Lightforge Ingots"] = "Слитки светлостали",
