t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Fly to Theramore"] = "Лететь на остров Терамор",
		["Greater Rock Elementals"] = "Большие каменные элементали",
		["Lesser Rock Elementals"] = "Младшие каменные элементали",
		["Maraudine centaurs"] = "Кентавры из племени Мародин",
		["Ogres and buzzards"] = "Огры и канюки",
		["Ride back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Вернитесь на запад к дороге и идите по ней на юг из зоны {zone:1432} через перевал в зону {zone:1418}. {npc:2910} и {npc:2860} стоят лагерем бок о бок у раскопок.",
		["Ride north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Езжайте на северо-восток к заброшенным раскопкам; ящик с припасами лежит там среди огров из клана Гнилобрюхов.",
		["Ride north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "Езжайте на северо-восток к руинам дворфов на севере зоны {zone:1418}; сундук стоит среди дворфов Тенегорна. {npc:2745} поблизости – элита: держитесь от него подальше.",
		["Rock Elementals"] = "Каменные элементали",
		["Shadowforge camp"] = "Лагерь Тенегорна",
		["Take the boat to Theramore from the far pier."] = "Сядьте на корабль до острова Терамор у дальнего причала.",
		["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east."] = "Огры из клана Гнилобрюхов стоят лагерем чуть южнее долины; лом падает с любого из них. Над равниной к востоку кружат канюки.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Каменные элементали бродят к юго-востоку от {npc:2921}; на равнине к западу от них – гигантские канюки и старые скальные койоты.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Дворфы Тенегорна стоят лагерем чуть севернее раскопок; смятая карта лежит среди их палаток. Кирка Ржанца – у проходчиков и темнопрядов. По склонам вокруг бродят скальные койоты.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "Разбитый скелет лежит чуть восточнее огров, на краю лагеря троггов из племени Каменного Свода; хлопья падают с костегрызов и шаманов вокруг. Тельдарин сидит у разрушенного лагеря дальше к югу.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Моллюски – на северо-западном побережье Тернистой долины, в следующем гайде: сохраните задание",
		["The excavation crate"] = "Ящик с раскопок",
		["The next guide starts in Theramore."] = "Следующий гайд начинается на острове Терамор.",
		["The skeleton's next task, Murdaloc, waits until the later {zone:1418} guide at 43."] = "Следующее задание скелета, «Мурдалок», подождет до более позднего гайда по зоне {zone:1418} на 43-м уровне.",
		["The wrecked ship's chest lies on the shore just west of {npc:11863}'s tower."] = "Сундук с разбитого корабля лежит на берегу чуть западнее башни {npc:11863}.",
		["The {object:126260}"] = "{object:126260}",
		["Theramore"] = "Остров Терамор",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Опустошители-отрекшиеся бродят по костяным полям к югу от деревни племени Маграм, к востоку от Ковена; на дальнем юго-востоке используйте {item:15848}, чтобы приманить призраков из племени Маграм.",
		["escort {npc:12277} back toward the graveyard"] = "сопроводите {npc:12277} обратно к кладбищу",
		["for the Dustwallow loop in the next guide"] = "для круга по Пылевым топям в следующем гайде",
		["for {npc:2786} in {zone:1455}: keep it"] = "для NPC {npc:2786} ({zone:1455}): сохраните задание",
		["for {npc:5637} in {zone:1455}: keep it"] = "для NPC {npc:5637} ({zone:1455}): сохраните задание",
		["only if you carry {item:2868} (a blacksmith's craft)"] = "только если у вас есть {item:2868} (изделие кузнеца)",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard."] = "{npc:12277} держат в лагере кентавров к западу от кладбища. Освободите ее и защищайте по пути наружу; она остановится у кладбища.",
		["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "{npc:12369}, вождь кентавров, стоит лагерем на северо-западном побережье, к северу от башни {npc:11863}.",
		["{npc:1470}, in the inn"] = "{npc:1470}, в таверне",
		["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590}: поймайте для задания «Мои маленькие друзья»",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, рядом с {npc:2921}",
		["{npc:2921}'s next test needs crafted gear: skip it."] = "Для следующего испытания {npc:2921} нужно изготовленное снаряжение: пропустите его.",
		["{npc:5638}'s next task, {item:6245}, is a drop on the far coast: skip it."] = "Следующее задание {npc:5638}, {item:6245}, – добыча на дальнем побережье: пропустите его.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "«Вонючка» Игнац",
		["Bloodsail camp"] = "Лагерь шайки Кровавого Паруса",
		["Bloodsail pirates"] = "Пираты из шайки Кровавого Паруса",
		["Cold Eye Basilisks"] = "Ледоглазые василиски",
		["Defeat the challengers and {npc:6238}"] = "Победите соперников и NPC {npc:6238}",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Смесь может выпасть с любого последователя Занзила; {npc:2537} ходит в южной части лагеря.",
		["Gorilla hills"] = "Холмы горилл",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "Сдайте клыки и оставайтесь на месте: придут три волны горилл, последним – {npc:1514}. Бейтесь с полным здоровьем.",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "Выйдите из города через туннель и идите вдоль побережья на север; письмо лежит в лагере шайки Кровавого Паруса на пляже, где ходит «Красавчик» Дункан.",
		["MacKinley's next task sends you after elite ogres: skip it."] = "Следующее задание Маккинли отправляет вас к элитным ограм: пропустите его.",
		["Mirefin murlocs"] = "Мурлоки из племени Болотного Плавника",
		["Mudrock tortoises"] = "Глинистые черепахи",
		["Naga Explorers"] = "Наги-исследователи",
		["Paladin: {quest:1661}"] = "Паладин: {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "Езжайте назад вниз в город; Трусишка стоит у входа в туннель.",
		["Ride back west along the road; {npc:217412} stands a short way north of Biggs."] = "Езжайте по дороге назад на запад; {npc:217412} стоит немного к северу от Биггса.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "Езжайте вглубь суши к холмам горилл Мглистой долины. Потроха падают со старых горилл из Мглистой долины; среди них сидит {npc:1449}.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "Езжайте на север к холмам к западу от дороги. {npc:2535} и {npc:2536} стоят вместе сразу к северу от деревни Занзила.",
		["Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale. On the way, an {npc:217588} crawls in the jungle south-east of Nesingwary's camp: catch one with the Entomology Starter Kit, then tick it off."] = "Езжайте на северо-восток мимо лагеря Эрнестуэя и по дороге на север к лагерю в верхней части долины. По пути в джунглях к юго-востоку от лагеря Эрнестуэя ползает {npc:217588}: поймайте его с помощью набора начинающего энтомолога, затем отметьте.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Езжайте от шахты на северо-запад к заливу на северо-западном побережье. На его дне лежат гигантские моллюски с жемчугом; среди них плавает {npc:2624}, с него падает {item:4034}.",
		["Ride south to the giant's hut in the middle of the marsh."] = "Езжайте на юг к хижине великана в середине болота.",
		["Riding at 40"] = "Верховая езда на 40-м уровне",
		["Seahorn's next errand goes back to Arathi: skip it."] = "Следующее поручение Морского Рога ведет обратно в Нагорье Арати: пропустите его.",
		["Skullsplitter ruins"] = "Руины Дробителей Черепов",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house."] = "Идите по дороге на север к разрушенной усадьбе; Ярл живет в лачуге рядом с ней, а рыхлая земля – у угла дома.",
		["The Bloodsail captains"] = "Капитаны шайки Кровавого Паруса",
		["The Cold Eye Basilisks lie on the rocks west of the mine."] = "Ледоглазые василиски лежат на скалах к западу от шахты.",
		["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes."] = "Пауки Мглистой пещеры гнездятся вокруг пещеры на северо-западе болота; глаза падают с каждого паука.",
		["The Mudrock Tortoises and Spikeshells sun themselves on the shore north-east of the manor."] = "Глинистые черепахи и глинистые колючие черепахи греются на берегу к северо-востоку от усадьбы.",
		["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do."] = "Тролли из племени Дробителей Черепов занимают руины сразу к востоку от шахты; клыки может уронить любой из них, а их пантеры – всегда.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes and the hoofprints are in the mud beside the inn."] = "Сгоревшая таверна стоит у дороги на запад, в сторону зоны {zone:1413}; значок стражника лежит в пепле, а следы копыт – в грязи рядом с таверной.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Дезертиры стоят лагерем к югу от дороги, к западу от хижины {npc:4503}.",
		["The driftwood washes up along the eastern shore."] = "Плавник выносит на восточный берег.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "Наги прочесывают пляжи к северу от лагеря шайки Кровавого Паруса; с них падает тростник.",
		["The north-west coast"] = "Северо-западное побережье",
		["The riddle's next scroll lies in western Dustwallow: skip it."] = "Следующий свиток загадки лежит на западе Пылевых топей: пропустите его.",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "Свиток лежит на болоте к северу от Биггса. С тинобродов к северу от него могут выпасть рассуждения Кадгара.",
		["The sunken temple"] = "Затонувший храм",
		["Theramore"] = "Терамор",
		["Unbagwa's ritual"] = "Ритуал Унбагвы",
		["Warlock: {quest:3631}"] = "Чернокнижник: {quest:3631}",
		["Zanzil's village"] = "Деревня Занзила",
		["for Stoley in {zone:1446}: keep it"] = "для Столи (зона {zone:1446}): сохраните",
		["for the {zone:1435} later"] = "для зоны {zone:1435}, позже",
		["for {npc:2616} in Theramore: keep it"] = "для NPC {npc:2616} (Терамор): сохраните",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "только если у вас есть {item:3853} (изготавливает кузнец)",
		["with the spices from Theramore"] = "со специями из Терамора",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}: для Ярла «Болотного Глаза»",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} готовит в здании {object:2169}; {npc:5384} – {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: другие цвета, 20 з.",
		["{npc:1356}: for {npc:1344} in {zone:1432}, keep it"] = "{npc:1356}: для NPC {npc:1344} (зона {zone:1432}), сохраните",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440} – Королевская библиотека ({object:2117})",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: {quest:93176}, из гайда по Нагорью Арати (30-40)",
		["{npc:217588}: catch it, for {quest:93176}"] = "{npc:217588}: поймайте для задания «{quest:93176}»",
		["{npc:2487}, top floor"] = "{npc:2487} – верхний этаж",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "Следующее поручение {npc:2498} про Занзила начинается в зоне {zone:1441}: пропустите его.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} и {npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} плавает у северо-западного побережья, на северном круге",
		["{npc:384}: other colours, 20g"] = "{npc:384}: другие цвета, 20 з.",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: другие цвета, 20 з.",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields."] = "{npc:4966} удерживает башню с несколькими дезертирами. Он нападет на вас: бейте его, пока он не сдастся.",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171} – в Соборе Света",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "Затем {npc:6236} предлагает задание «Ветростраж» (1791): цепочка оружия Вихря с элитным противником в конце описана в классовом гайде воина «Оружие Смерча».",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: для задания «{quest:2864}» (зона {zone:1446}), сохраните",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: другие цвета, 20 з.",
		["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910} – высокое здание над гаванью; большинство дающих задания – на его этажах или на причалах внизу.",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "Задание «{quest:1260}» – у таверны; {npc:4897}, поставщица в нескольких шагах к югу, продает специи, которые нужны Ярлу.",
		["{zone:1453} has no shaman trainer"] = "В городе {zone:1453} нет учителя шаманов",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Blue Pearls from Stranglethorn"] = "Синие жемчужины из Тернистой долины",
		["On to Feathermoon"] = "В Крепость Оперенной Луны",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Езжайте на юг из зоны {zone:1432} через перевал в зону {zone:1418}; {npc:2860} стоит лагерем у раскопок.",
		["Take the boat to Theramore from the far pier."] = "Сядьте на корабль до острова Терамор у дальнего причала.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "Следующее задание Разящего Когтя подождет до более позднего гайда по {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Обжигающие дракончики гнездятся в ущелье к востоку (ориентир: {npc:2888}); опаленных стражей (элита) не трогайте. {item:4612} падает редко: возьмите, если выпадет, пока вы фармите.",
		["The battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers."] = "Разбитый скелет лежит на краю лагеря троггов из племени Каменного Свода; убийца Эгмонда ({quest:739}) ходит среди костегрызов.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "Первые две клетки стоят рядом в деревне племени Сухокожих к югу от {npc:5634}; третья – в следующей деревне к востоку. Ожерелье может упасть с любого тролля из племени Сухокожих.",
		["Theramore"] = "Остров Терамор",
		["Warlock: {quest:3631}"] = "Чернокнижник: {quest:3631}",
		["Witherbark villages"] = "Деревни племени Сухокожих",
		["{npc:1573}, the {object:32372}"] = "{npc:1573}, {object:32372}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} стоит на причале, куда прибывает корабль.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "{npc:2817}: следующее задание не дает опыта, пропустите его.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "{npc:2888}: следующее задание – охота на элиту, пропустите его.",
		["{npc:5634}'s cocktail needs parts from Kalimdor: skip it."] = "Для коктейля {npc:5634} нужны ингредиенты из Калимдора: пропустите задание.",
		["{npc:5636}, beside the flight master at the top"] = "{npc:5636}, наверху рядом с распорядителем полетов",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884} продолжает платить за ожерелья: сдайте лишние",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Giants and elementals"] = "Великаны и элементали",
		["Gordunni ogres"] = "Огры из клана Гордунни",
		["Grimtotem camp"] = "Лагерь Зловещего Тотема",
		["Grimtotem tauren"] = "Таурены из племени Зловещего Тотема",
		["Grind to 45"] = "Гринд до 45",
		["Hatecrest naga"] = "Наги из клана Гребня Ненависти",
		["Hearth to Feathermoon."] = "Используйте Камень возвращения: Крепость Оперенной Луны.",
		["Rage Scar yetis"] = "Йети Бешеного оврага",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "Езжайте обратно на запад по дороге, затем на север к холмам Бешеного оврага. С любого йети здесь может выпасть шкура; с одного может выпасть {quest:7735}, за нее {npc:7852} тоже платит.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Езжайте на восток к Поселению Гордунни на холмах к юго-востоку от долины йети: в лагере чернокнижники и шаманы, громилы бродят по склонам вокруг и севернее.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Езжайте на север в долину йети. С любого йети со Свирепого Утеса может выпасть толстая шкура; {npc:5346} (уровень 48) рыщет в центре.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Езжайте на северо-восток к заставе ночных эльфов на границе зоны {zone:1441}.",
		["Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room."] = "Езжайте на запад к дружелюбному горному великану у подножия холмов. Сухопутные бродяги и скальные великаны вокруг него — элита: держитесь подальше.",
		["Ring the bell whenever {npc:7774} stops to wander, and lead her south to {npc:7765}."] = "Звоните в колокольчик всякий раз, когда {npc:7774} останавливается побродить, и ведите ее на юг к NPC {npc:7765}.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Береговые странники, странники глубин и странники волн (элитные великаны) бродят по мелководью к северу от причала: ударьте одного предметом {item:18904} и убейте уменьшенного великана. Морские элементали и морские валы плавают в том же прибое.",
		["The courier's boat"] = "Лодка курьера",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Идите на юг по острову к руинам наг; беседка стоит среди них.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "для Тиранды ({zone:1457}): маршрут приведет вас туда на 47-м уровне",
		["if you carry {quest:1100} from {zone:1441}"] = "если у вас есть {quest:1100} из зоны {zone:1441}",
		["{item:11463}, from the backpacks"] = "{item:11463}, из рюкзаков",
		["{npc:14637}'s refills are level 55: skip them."] = "Пополнения {npc:14637} — 55-го уровня: пропустите их.",
		["{npc:3936}, beside him"] = "{npc:3936}, рядом с ним",
		["{npc:7774} wanders the hills north of {npc:7765}, among the Northspring harpies; her bell is in the chest beside her."] = "{npc:7774} бродит по холмам к северу от NPC {npc:7765}, среди гарпий из стаи Студеных Ключей; ее колокольчик в сундуке рядом.",
		["{npc:7774}'s escort"] = "Сопровождение: {npc:7774}",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, на вершине крепости",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} ждет до конца круга по материку.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp."] = "Идите вдоль побережья на юг к пиратской бухте. Пираты Южных морей заполонили пляж и корабли: двигайтесь по краю и выманивайте по одному. {npc:7883} стоит на дальней стороне; украденный груз ({npc:7881}) лежит в лагере.",
		["Gives the {item:8585}"] = "Дает: {item:8585}",
		["He runs off to keep Rizzle busy"] = "Он убегает отвлечь Риззла",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Езжайте на восток через дюны к гоблинской гавани на северо-восточном побережье.",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts."] = "Езжайте на северо-запад к улью сентипааров в дюнах. С любого сентипаара могут выпасть части насекомых.",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time."] = "Езжайте на юг: {quest:3362}. Железы падают с терновых собирателей росы; полные не все, так что сохраните насыщенную. В долине также бугристые шипокожи и терновые корнеплеты. Шипокожи 48-50 уровня, выше вас: выманивайте по одному.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Езжайте на юго-запад к поселению огров. Там полно громил и головорезов (46-48); {npc:12046} (49) стоит в центре в окружении стражи: сначала разберитесь с ней.",
		["Rizzle's plans"] = "Чертежи Риззла",
		["The Wanted poster beside him"] = "Плакат «Розыск!» рядом с ним",
		["Wastewander bandits"] = "Бандиты из шайки Скитальцев Пустыни",
		["While {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "Пока {npc:4709} заговаривает Риззлу зубы, его чертежи лежат без охраны в лагере гномов по ту сторону трассы.",
		["for {zone:1457}: the route takes you there at 47"] = "Для зоны {zone:1457}: маршрут приведет вас туда на 47-м уровне",
		["{npc:11758}, on the east side of town"] = "{npc:11758}, восточная часть городка",
		["{npc:5955}'s escort"] = "Сопровождение: {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, у водонапорной башни",
		["{npc:7408}, next to him"] = "{npc:7408}, рядом с ним",
		["{npc:7583}'s next ingredient grows in the {zone:1425}, and the route never brings it back: skip it."] = "Следующий ингредиент ({npc:7583}) растет здесь: {zone:1425}, а маршрут никогда не приводит его обратно: пропустите.",
		["{npc:7881}, in the port's tavern"] = "{npc:7881}, в таверне порта",
		["{quest:2864}, north side of town"] = "{quest:2864}, северная часть городка",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Ashmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52."] = "Пеплогривые кабаны и краснокаменные василиски обитают на склонах к юго-западу от крепости. Держитесь подальше от зловепрей южнее: у них 52-й уровень.",
		["Boars and basilisks"] = "Кабаны и василиски",
		["Hearthstone on cooldown? Ride back north-west."] = "Камень возвращения на перезарядке? Езжайте обратно на северо-запад.",
		["Ride back north to Ironband's camp."] = "Езжайте обратно на север к Раскопкам Сталекрута.",
		["Ride east along the south shore of the loch to Ironband's camp."] = "Езжайте на восток вдоль южного берега озера к лагерю: Раскопки Сталекрута.",
		["Ride east through {zone:1430} into the {zone:1435} and south down the road into the {zone:1419}. The bloodmages' camp is the first stop beside the road."] = "Езжайте на восток через {zone:1430} в {zone:1435} и на юг по дороге в {zone:1419}. Лагерь магов крови — первая остановка у дороги.",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time."] = "Езжайте на запад: голодные хохотуны бродят по сухим холмам чуть южнее лагеря магов крови; скорпоки-острожалы (уровень 50) снуют по центру северной части. Над всем этим кружат грифы ({npc:5982}). Выманивайте по одному.",
		["Scorpoks and snickerfangs"] = "Скорпоки и хохотуны",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Пройдите через портал в {zone:1457}. Храм Луны — на юге города.",
		["Temple of the Moon"] = "Храм Луны",
		["The bloodmages"] = "Маги крови",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "Вторая ступень заданий магов крови платит за те же части предметом-усилением без опыта: пропустите.",
		["The druid trainers stand in the Enclave; {zone:1455} has none"] = "Учителя друидов стоят в Анклаве; в городе {zone:1455} их нет",
		["the book on her table"] = "книга на ее столе",
		["the soil comes from {zone:1449}, later"] = "почва — из зоны {zone:1449}, позже",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, на вершине дерева",
		["{npc:7740}, beside her"] = "{npc:7740}, рядом с ней",
		["{npc:7744}: the last guide binds here, so this usually ticks at once"] = "{npc:7744}: предыдущий гайд привязывает вас здесь, так что это обычно отмечается сразу",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "Следующее поручение {npc:7907} ведет в {zone:1446}: пропустите.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916}: сохраните задание, перья будут в конце гайда по зоне {zone:1428}",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, на вершине крепости",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["For {npc:8256} in {zone:1455}, later"] = "Для NPC {npc:8256} ({zone:1455}), позже",
		["Golems and elementals"] = "Големы и элементали",
		["Greater Lava Spiders"] = "Большие лавовые пауки",
		["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "Тяжелые боевые големы патрулируют дно Котлована под Калараном; среди них плавают элементали магмы. Масло падает с големов и элементалей, сердца — с элементалей.",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it."] = "Надсмотрщики и поработители гоняют рабов по всему Котловану, и у любого из них может быть {item:10551}. Кузнецы работают у печей в центре ({item:18959}), наблюдатели стоят на южных гребнях (подзорная труба наблюдателя). С любого противника ({object:147516}) может выпасть {item:11818}: сохраните его.",
		["The Grimesilt outhouse"] = "Нужник Карьера Грязнули",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "Следующее задание пленника, «Учетная книга из Танариса» ({zone:1446}), ведет в {zone:1435} и {zone:1445}: пропустите.",
		["The spiders roam the plateaus and lava pools in the south-west of the gorge."] = "Пауки бродят по плато и лавовым озерам на юго-западе ущелья.",
		["The {object:179827} board"] = "Доска: {object:179827}",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}: предыдущий гайд возвращает вас сюда камнем возвращения, так что это обычно отмечается сразу",
		["{object:147516} dwarves"] = "Дворфы: {object:147516}",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Аркессон стоит рядом с королем Магни ({object:171709}).",
		["Bind and train"] = "Привяжите камень и обучитесь",
		["Bones and equipment"] = "Кости и оборудование",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Пересеките юг кратера и вернитесь к {npc:9619} у спуска.",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Кости динозавров лежат на земле на юго-западе, среди стегодонов: они элитные, поэтому подбирайте кости вокруг них, а остальные добывайте с деметродонов. {item:11112} экспедиции лежит в юго-западных джунглях.",
		["Eastern Pylon"] = "Восточный пилон",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Завершается у NPC {npc:9298} (зона {zone:1452}): сохраните",
		["Escort {npc:9999}"] = "Сопроводите NPC {npc:9999}",
		["For {npc:7775} in {zone:1444}: keep it"] = "Для NPC {npc:7775} (зона {zone:1444}): сохраните",
		["Four rune rubbings in {zone:1447}: keep it"] = "Четыре оттиска рун в зоне {zone:1447}: сохраните",
		["Grind to 50"] = "Добейте 50-й уровень",
		["Grind to 51"] = "Добейте 51-й уровень",
		["Lar'korwi Mates and the raft"] = "Самки Лар'корви и плот",
		["Northern Pylon"] = "Северный пилон",
		["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "Езжайте по спуску вниз в кратер: {npc:9619} стоит лагерем у его подножия.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Езжайте на север по восточной стороне к плато горилл. {npc:9622}, горилла 55-го уровня, сидит в самой глубокой пещере: сначала перебейте горилл у входа.",
		["Ride north along the western jungle back to the refuge."] = "Езжайте на север через западные джунгли назад в укрытие.",
		["Ride south along the eastern cliffs to {npc:9619} at the foot of the ramp."] = "Езжайте на юг вдоль восточных утесов к {npc:9619} у подножия спуска.",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "Езжайте на юг по восточной стороне. Молодые деметродоны пасутся в восточных джунглях, а у восточных утесов летает {npc:9165}; с тех и других падает чешуя для NPC {npc:9998}.",
		["Ride west back to the refuge."] = "Езжайте на запад назад в укрытие.",
		["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; {npc:9166} nest on the southern cliffs if you still need kills."] = "Езжайте от {npc:9619} на запад: улей силитидов занимает юг кратера. Используйте фиал для образцов на инкубаторе – камере со свисающими личинками. С ос и рабочих из улья Гориши падает предмет для задания «{quest:3764}»; если вам еще нужны убийства, на южных утесах гнездится {npc:9166}.",
		["The Gorishi hive"] = "Улей Гориши",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Самки Лар'корви рыщут по джунглям к западу от {npc:9619}. Разбитый плот лежит там на берегу озера; маленький рюкзак – в воде рядом с ним. Компас, карту и ключ сохраните для NPC {npc:8737}. С любого зверя в кратере может выпасть {item:11116}: щелкните по нему правой кнопкой.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "Мертвый жесткозуб лежит у воды к северу от {npc:9619}.",
		["The east side"] = "Восточная сторона",
		["The pelts come after loop 2, on the gorilla plateau"] = "Шкуры – после 2-го круга, на плато горилл",
		["The pylon stands on the eastern cliffs."] = "Пилон стоит на восточных утесах.",
		["The pylon stands on the slope east of the refuge. {npc:9166} circle the slopes around it: they count for {npc:9997} and drop {npc:9998}'s scales."] = "Пилон стоит на склоне к востоку от укрытия. {npc:9166}: кружат над склонами вокруг него, засчитываются для {npc:9997} и роняют чешую для NPC {npc:9998}.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "Пилон стоит на западных утесах. {npc:9167}: летают над всей западной стороной.",
		["The relics are in the {zone:1428}: keep it"] = "Реликвии – в зоне {zone:1428}: сохраните",
		["The wooden sign beside {npc:9997}"] = "Деревянная табличка рядом с NPC {npc:9997}",
		["Western Pylon"] = "Западный пилон",
		["Xiggs waits in the {object:32359}."] = "Зиггс ждет здесь: {object:32359}.",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}: для Огтинка (зона {zone:1447}), сохраните",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}: предыдущий гайд возвращает вас сюда камнем возвращения, так что это обычно отмечается сразу",
		["{npc:9117}, at the back of the cave"] = "{npc:9117} – в глубине пещеры",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: слизни – в зоне {zone:1448}, сохраните",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618} стоит сразу у входа в укрытие.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "Логово зверя {npc:9684} – в джунглях к северу от {npc:9619}, под восточными утесами: используйте там {item:11568}. {npc:9684} – 56-го уровня: начинайте бой с полным здоровьем.",
		["{npc:9997}'s friend {npc:9999} has gone missing."] = "Пропал друг {npc:9997} – {npc:9999}.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998} – у входа в укрытие",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998} – у входа в укрытие",
} end)()
