t.guides["forever/horde/30-40/02-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Обратно на север к лагерю.",
		["Back to {object:3202}"] = "Вернитесь: {object:3202}",
		["Back to {object:3202}."] = "Вернитесь: {object:3202}.",
		["Basilisks and the Bloodscalp village"] = "Василиски и деревня Кровавого Скальпа",
		["Bloodscalp headhunters"] = "Охотники за головами из племени Кровавого Скальпа",
		["Bloodscalp ruins"] = "Руины Кровавого Скальпа",
		["East of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}."] = "К востоку от огров тенебрюхие пантеры (37-38) крадутся незаметно, пока не нападут; там же бродят тигрицы Тернистой долины, иногда роняющие безупречный клык. Кроколиски-хрустогрызы лежат вдоль реки чуть западнее джунглей; сохраните их шкуры для NPC {npc:2495}.",
		["Elder tigers and Lashtail raptors"] = "Старые тигры и ящеры-кнутохвосты",
		["Fly to {object:3202}"] = "Летите: {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "Идите по дороге на север из места {object:3202}; охотничий лагерь Эрнестуэя — на холме к северо-востоку от реки. С этого момента сохраняйте каждую страницу из книги «{quest:338}»: позже их попросит {npc:716}.",
		["Follow the road south to {object:3202}."] = "Идите по дороге на юг: {object:3202}.",
		["Green Hills pages"] = "Страницы «Зеленых холмов»",
		["Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it."] = "Идите на запад мимо лагеря. Ящеры Тернистой долины (33-34) охотятся на полянах, а тролли из племени Кровавого Скальпа занимают руины на побережье: с любого из них может выпасть бивень. {item:4614} падает с них очень редко: если выпадет, прочтите ее.",
		["Hearth to {object:3202}"] = "Используйте Камень возвращения: {object:3202}",
		["Jungle Stalkers"] = "Тропические ловцы",
		["Lashtail raptors"] = "Ящеры-кнутохвосты",
		["Leave the {zone:1458} by the lift and walk up through the ruins to the zeppelin towers; the {object:3202} zeppelin is the one on the south-west tower."] = "Выйдите из города {zone:1458} на лифте и поднимитесь через руины к башням дирижаблей; дирижабль ({object:3202}) — на юго-западной башне.",
		["Mistvale gorillas"] = "Гориллы Мглистой долины",
		["Mosh'Ogg camp"] = "Лагерь Мош'Огг",
		["Nesingwary's camp"] = "Лагерь Эрнестуэя",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "Страницы книги «{item:2755}» падают с шансом около 1% каждая с троллей из племен Кровавого Скальпа и Дробителей Черепов; сохраняйте каждую найденную страницу, а остальные поищите на аукционе. {npc:716} принимает главы позже в этом гайде.",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; take what drops and check the Auction House for the rest."] = "Страницы книги «{item:2755}» падают с шансом около 1% каждая с троллей из племен Кровавого Скальпа и Дробителей Черепов; берите, что выпадет, а остальное ищите на аукционе.",
		["Raptors and the Bloodscalp trolls"] = "Ящеры и тролли из племени Кровавого Скальпа",
		["Ride back south to {object:3202}."] = "Езжайте обратно на юг: {object:3202}.",
		["Ride north past Nesingwary's camp to the lake. The Venture Co. Geologists (34-36) work the camps along its western shore; they carry the Tumbled Crystals."] = "Езжайте на север мимо лагеря Эрнестуэя к озеру. Геологи Торговой компании (34-36) работают в лагерях вдоль его западного берега; у них упавшие кристаллы.",
		["Shadowmaw jungle and the Snapjaw river"] = "Джунгли тенебрюхих пантер и река хрустогрызов",
		["Shadowmaw panthers"] = "Тенебрюхие пантеры",
		["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "Тигры Тернистой долины и пантеры (32-33) бродят по холмам к востоку от лагеря, вдоль берега озера.",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202} and train in the city before you fly on."] = "Летите на дирижабле ({zone:1454}) от башни на западной стороне места {object:3202} и обучитесь в городе перед дальнейшим полетом.",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads."] = "Сушеные головы у охотников за головами из племени Кровавого Скальпа (36-37) в деревне на побережье.",
		["The Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "Тролли из племени Кровавого Скальпа занимают руины на побережье к северу от рифа и деревню дальше; с любого может выпасть {item:3915}. Продолжайте собирать страницы из книги «{quest:338}».",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp; the Lashtail Raptors (35-36) hunt further south, towards {object:3202}."] = "Старые тигры Тернистой долины (34-35) бродят по холмам к юго-западу от лагеря; ящеры-кнутохвосты (35-36) охотятся южнее, в сторону места {object:3202}.",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "Тропические ловцы (40-41) охотятся на побережье к югу от места {object:3202}. Они намного выше вас: выманивайте по одному и отдыхайте между боями.",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "Ящеры-кнутохвосты (35-36) охотятся в джунглях чуть северо-восточнее места {object:3202}.",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}. Kill one Brute and one Witch Doctor (36-37); pull them one at a time."] = "Огры из клана Мош'Огг стоят лагерем на холмах чуть восточнее места {object:3202}. Убейте одного громилу и одного знахаря (36-37); выманивайте по одному.",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "Тенебрюхие пантеры (37-38) крадутся по джунглям к востоку от холмов Мош'Огг и на северо-восток к озеру; они нападают из невидимости. Собирайте по пути каждую страницу «Зеленых холмов».",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Тенебрюхие пантеры будут гораздо позже, у объекта {object:3202}",
		["The camp by the river"] = "Лагерь у реки",
		["The zeppelin lands at the tower on the west side of the camp."] = "Дирижабль приземляется у башни на западной стороне лагеря.",
		["Tigers and panthers"] = "Тигры и пантеры",
		["Venture Co. camp"] = "Лагерь Торговой компании",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear."] = "К западу от лагеря на камнях сидят хрустальные василиски (34-35); с любого тролля из племени Кровавого Скальпа в деревне дальше может выпасть ухо.",
		["Young Stranglethorn Tigers prowl west of the camp, Young Panthers south and east of it."] = "Молодые тигры Тернистой долины рыщут к западу от лагеря, молодые пантеры — к югу и востоку.",
		["Young tigers and panthers"] = "Молодые тигры и пантеры",
		["Zeppelin to {object:3202}"] = "Дирижабль: {object:3202}",
		["Zeppelin towers"] = "Башни дирижаблей",
		["{npc:2495}: the Snapjaw skins gathered earlier"] = "{npc:2495}: собранные ранее шкуры хрустогрызов",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: для Нагорья Арати, позже по маршруту",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527} и ваш {item:5177}",
		["{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp."] = "{npc:729}, тигр 37-го уровня, рыщет на вершине холма к юго-западу от лагеря.",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "Лагерь пропавших охотников ({npc:773}) — это лагерь Эрнестуэя: пройдите между палатками, и расследование завершится. Речные кроколиски лежат вдоль реки ниже лагеря.",
} end)()
t.guides["forever/horde/30-40/03-arathi-highlands"] = (function() return {
		["Boulderfist camp"] = "Лагерь клана Тяжелого Кулака",
		["Coyotes and buzzards"] = "Койоты и канюки",
		["Daggerspine shore"] = "Берег наг Пронзающего Гребня",
		["Escort the professor down to the shore. Two Daggerspine naga ambush him on the way: stay close."] = "Сопроводите профессора к берегу. По пути на него нападут две наги из клана Пронзающего Гребня: держитесь рядом.",
		["Fleshstalker raptors"] = "Ящеры-плотоглоты",
		["Fly to {object:3202}"] = "Летите сюда: {object:3202}",
		["Follow the road north; {npc:4618}'s camp is on the way."] = "Идите по дороге на север; лагерь {npc:4618} – по пути.",
		["Greater Rock Elementals"] = "Большие каменные элементали",
		["Highland raptors"] = "Ящеры нагорья",
		["Into the {zone:1418}"] = "В край {zone:1418}",
		["Lesser Rock Elementals"] = "Младшие каменные элементали",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael."] = "К северо-востоку от Павшего Молота кобольды из племени Сухоусов копают в ущелье; с кобольдов у входа и с землекопов и геодезистов в глубине падает «Мощь Мизраэли».",
		["Ride north; the outer circle stands in the middle of the highlands."] = "Езжайте на север; внешний круг – в центре нагорья.",
		["Ride south-west to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "Езжайте на юго-запад к бухте гоблинов на южном побережье. {npc:2766} стоит на скале над ней.",
		["Rock Elementals"] = "Каменные элементали",
		["Stonevault troggs"] = "Трогги Каменного Свода",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202}."] = "Садитесь на дирижабль ({zone:1454}) с башни в западной части лагеря ({object:3202}).",
		["The Greater Rock Elementals (42-44, well above you) wander the gulches in the south-west; the bracers drop about one kill in five. Pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "Большие каменные элементали (42-44, намного выше вас) бродят по ущельям на юго-западе; наручи падают примерно с каждого пятого. Выманивайте по одному и отдыхайте между боями – или пропустите их. По пути добивайте нужных вам койотов и канюков.",
		["The Syndicate hold the walled manor and its farm in the north-west; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets."] = "Синдикат занимает обнесенную стеной усадьбу и ферму на северо-западе; амулеты Кровавого камня носят проходимцы, наемники и налетчики Синдиката.",
		["The Witherbark trolls hold the village in the south-eastern hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village."] = "Тролли племени Сухокожих занимают деревню на юго-восточных холмах. Метатели топоров охраняют крайние хижины; знахари и охотники за головами – в центре деревни.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Внутренний круг – к югу от западного, к востоку от Стромгарда.",
		["The next guide heads into {zone:1445}."] = "Следующее руководство ведет в край {zone:1445}.",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate."] = "Крепость орков в восточном конце дороги. {npc:2851}, распорядитель полетов, стоит у ворот.",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "Маленькие элементали бродят по равнине чуть к западу от лагеря {npc:2921}. С любого каменного элементаля в зоне могут падать осколки каменного элементаля для {npc:6868}: сохраните их.",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "Следующее задание камня требует убить Фозрука (элита 42-го уровня): не берите его.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2689}"] = "{object:2689}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} – в дальнем конце ущелья.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Обучитесь, пока вы здесь ({zone:1458}): учителя – здесь: {object:36070}, {object:36073} и {object:36082} (паладины: {npc:260093}).",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "К западу от бухты налетчики и колдуньи из клана Пронзающего Гребня (38-40) занимают берег: выманивайте по одному. Два затонувших корабля лежат на мелководье, карты и журналы – внутри; самоцветы лежат на дне вокруг кораблей.",
		["Zeppelin to the {zone:1458}"] = "Дирижабль: {zone:1458}",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["Zeppelin tower"] = "Башня дирижаблей",
		["for {npc:5395} in {zone:1443}, in the next guide"] = "для персонажа {npc:5395} ({zone:1443}), в следующем руководстве",
		["{item:3713}, for \"Swamp Eye\" Jarl in {zone:1445}"] = "{item:3713}, для Ярла «Болотного Глаза» ({zone:1445})",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "Следующее задание ({quest:678}, {npc:2771}) – против элитных огров Тяжелого Кулака: не берите его.",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920}: только если у вас есть {item:2868} ({skill:164} или аукцион)",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "Здесь ({object:1661}) нет учителей охотников и шаманов: садитесь на дирижабль с той же башни ({zone:1454}) и обучитесь в городе, затем садитесь на дирижабль ({zone:1458}) с башни у главных ворот ({zone:1454}).",
		["{zone:1458} trainers"] = "Учителя: {zone:1458}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Darkfang spiders"] = "Пауки-темножвалы",
		["For {npc:2519} at {object:3202}, in the next guide"] = "Для персонажа {npc:2519} ({object:3202}), в следующем руководстве",
		["Hearth to Shadowprey"] = "Камень возвращения: Деревня Ночных Охотников",
		["Kodo bones and ghosts"] = "Кости кодо и призраки",
		["Maraudine totems"] = "Тотемы Мародин",
		["Mirefin murlocs"] = "Мурлоки Болотного Плавника",
		["Pick up the kodo bones scattered across the graveyard, and use the {item:15848} among the bones: the ghosts it draws drop the ghost-o-plasm."] = "Собирайте кости кодо по всему кладбищу и используйте предмет {item:15848} среди костей: с призванных призраков падает призракоплазма.",
		["Ride back west to Brackenwall with the head."] = "Возвращайтесь с головой на запад в Гиблотопь.",
		["Ride north up the road to the hut by the road north of the graveyard."] = "Езжайте на север по дороге к хижине у дороги к северу от кладбища.",
		["Ride on south-west to Shadowprey."] = "Езжайте дальше на юго-запад к Деревне Ночных Охотников.",
		["Ride west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "Возвращайтесь на запад через болото. С ядоплюев-темножвалов на холмах к северу от Гиблотопи падают ядовитые железы. Тераморские секретные агенты (35-36) крадутся в тех же лесах: они незаметны, смотрите внимательно.",
		["Slitherblade coast"] = "Берег Скользящего Плавника",
		["Stinky Ignatz"] = "«Вонючка» Игнац",
		["Swamp Eye Jarl"] = "Ярл «Болотный Глаз»",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "На развилке сверните на север к деревне огров Гиблотопь.",
		["The Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes."] = "Пауки Мглистой пещеры кишат у входа в пещеру к северо-западу от Гиблотопи; глаза падают со всех видов.",
		["The next guide takes you back to {zone:1434}."] = "Следующее руководство вернет вас сюда: {zone:1434}.",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "только если у вас есть {item:3853} ({skill:164} или аукцион)",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, на южном краю деревни, у въезда",
		["{npc:5395} and {npc:5412} stand in the post just west of {npc:11596}'s camp."] = "{npc:5395} и {npc:5412} стоят в лагере чуть к западу от лагеря {npc:11596}.",
		["{npc:6791}: the last guide binds here, so this usually ticks at once"] = "{npc:6791}: предыдущий гайд привязывает вас здесь, так что это обычно отмечается сразу",
		["{object:20985}, beside the manor"] = "{object:20985}, у усадьбы",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, теперь, когда {npc:4791} прочел донесение",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Draenethyst crystals"] = "Кристаллы дренетиста",
		["Fly to {object:3202}"] = "Летите сюда: {object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "Идите вдоль берега на юг. Наги-исследователи бродят по берегу и носят связки тростника; {object:759} бурлит в холмах чуть к востоку.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals."] = "Дальше к северу гоблины Торговой компании копают в руднике к востоку от дороги; кристаллы падают с шахтеров, десятников, геодезистов и механиков.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "Отдайте Унбагве клыки и оставайтесь рядом: он призовет три волны горилл, затем {npc:1514}. Бейтесь с ними по одному.",
		["Hearth to {object:3202}"] = "Камень возвращения: {object:3202}",
		["Into the {zone:1435}"] = "В край {zone:1435}",
		["Jungle stalkers"] = "Ящеры-ловчие",
		["Mistvale gorillas"] = "Гориллы из Мглистой долины",
		["Naga shore and the {object:759}"] = "Берег наг и {object:759}",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "К северо-востоку от Мглистой долины в джунглях стоят лагерем последователи Занзила; смесь может быть у любого из них.",
		["Pirate ghosts"] = "Призраки пиратов",
		["Ride north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "Езжайте на север к руинам племени Дробителей Черепов к востоку от рудника Торговой компании; выманивайте охотников за головами и берсерков по одному. {npc:1059} охраняет юго-западные руины, а одна груда трофейных черепов стоит в северной части руин. С любого тролля Дробителей Черепов может упасть клык или ожерелье: ожерелья падают медленнее, поэтому бейте воинов в лагере к северу от руин, пока не соберете все.",
		["Ride north up the road to the hunters' camp."] = "Езжайте на север по дороге к лагерю охотников.",
		["Ride north up the road; the hunters camp on the hill above the river."] = "Езжайте на север по дороге; лагерь охотников – на холме над рекой.",
		["Ride north-west to {object:3202}."] = "Езжайте на северо-запад сюда: {object:3202}.",
		["Ride west to {object:3202}."] = "Езжайте на запад сюда: {object:3202}.",
		["Sawtooth crocolisks"] = "Острозубые кроколиски",
		["Sawtooth snappers"] = "Острозубые крепкохваты",
		["Skullsplitter warriors"] = "Воины из племени Дробителей Черепов",
		["The Bloodsail ships"] = "Корабли Кровавого Паруса",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Гориллы бродят по долине вокруг Унбагвы. Потроха падают со старых горилл; клык может упасть с любой.",
		["The last skulls are in the ruins a short ride west, on the way back to {object:3202}."] = "Последние черепа – в руинах недалеко к западу, по пути обратно сюда: {object:3202}.",
		["The next guide starts here and takes you to {zone:1446}."] = "Следующее руководство начинается здесь и ведет в край {zone:1446}.",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp."] = "Следующие трофейные черепа – в небольших руинах чуть к северу от лагеря воинов.",
		["The snappers line the strand south of the post."] = "Крепкохваты сидят на берегу к югу от лагеря.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "Ящеры-ловчие охотятся в джунглях к югу от места {object:3202}, ближе к западному побережью.",
		["Venture Co. mine"] = "Рудник Торговой компании",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "К западу от экспедиции вожди племени Кровавого Скальпа – {npc:1061} и {npc:1062} – стоят вместе в руинах Зул'Кунды. Сначала перебейте охрану, затем выманите их.",
		["Zanzil's camps"] = "Лагеря Занзила",
		["Zul'Kunda"] = "Зул'Кунда",
		["Zul'Mamwe"] = "Зул'Мамбве",
		["for Stoley in {zone:1446}"] = "для Столи ({zone:1446})",
		["for a later stop in the {zone:1435}"] = "для более поздней остановки ({zone:1435})",
		["for later: the {zone:1425}, around level 48"] = "на потом: {zone:1425}, примерно на 48-м уровне",
		["the {object:2076}"] = "{object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "{object:2076}, рядом: {npc:2497}",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Eastern Wastewander camps"] = "Восточные лагеря Скитальцев Пустыни",
		["Fly to {object:3202}"] = "Летите сюда: {object:3202}",
		["Grimtotem camp"] = "Лагерь Зловещего Тотема",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "Езжайте дальше на запад к побережью. С береговых глубинников и клешнехватов на пляжах примерно один раз из сорока падает аварийный маяк OOX-22/FE: если выпадет, используйте его, чтобы начать задание.",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "К северу от гноллов огры занимают заставу на холме; выманивайте огров-магов к себе. Кобальт – в кучах земли вокруг заставы, а свиток лежит на земле внутри.",
		["Ride north-east to the goblin harbour on the coast."] = "Езжайте на северо-восток к гоблинской гавани на побережье.",
		["Ride west into the middle of {zone:1444}. Kill a {npc:5308}, use {item:10699} on its body and kill the spirit that rises."] = "Езжайте на запад в центр края {zone:1444}. Убейте монстра {npc:5308}, примените на тело предмет {item:10699} и убейте поднявшийся дух.",
		["Riding at 40"] = "Верховая езда на 40-м уровне",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel; no Skyborne riding trainer is known, so Skyborne try {npc:4752} too. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "Верховая езда требует 40-го уровня и стоит 100 золотых; при обучении вы получаете транспорт. {npc:4752} обучает орков, ориентир: {object:172958}, у псарни ({npc:3362}); учитель верховой езды для небеснорожденных неизвестен, поэтому небеснорожденным тоже стоит попробовать персонажа {npc:4752}. Другой транспорт вашей расы стоит по 20 золотых: в разделе «Коллекции», «Транспорт · 40-й уровень» есть гайд для каждого.",
		["Rogue Vale screechers"] = "Крикуны Разбойничьей долины",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often."] = "Дальше на юг вдоль берега бухту занимают пираты Южных морей. {npc:7883} и украденный груз – на причале в дальнем конце. Шляпа может упасть с любого пирата, чаще всего с похитителей.",
		["Southern Gordunni ruins"] = "Южные руины Гордунни",
		["Southern Wastewander camps"] = "Южные лагеря Скитальцев Пустыни",
		["Sprite darters and Woodpaw alphas"] = "Летучие хамелеоны и вожаки Древолапов",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Таурены племени Зловещего Тотема стоят лагерем у рощи хамелеонов; рога есть у налетчиков, натуралистов и шаманов.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane."] = "Гноллы из стаи Древолапов стоят лагерем на холмах чуть к северо-западу от Лагеря Мохаче; грива может упасть с любого.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "Улей Цуккаш врыт в холмы к юго-востоку от лагеря; {quest:7731} ждет в самой дальней камере.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "Тактическая карта лежит в лагере Древолапов к югу от Лагеря Мохаче.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour."] = "Летучие хамелеоны порхают над рощей чуть к западу от Лагеря Мохаче; крыло падает почти с каждого. Вожаки стаи Древолапов возглавляют лагеря к юго-западу: убейте их в течение часа.",
		["The {object:3202} zeppelin leaves from the tower just north-east of {zone:1454}'s main gate."] = "Дирижабль ({object:3202}) отправляется с башни чуть к северо-востоку от главных ворот ({zone:1454}).",
		["The {zone:1454} zeppelin leaves from the tower beside {object:3202}; it lands just outside {zone:1454}'s main gate."] = "Дирижабль ({zone:1454}) отправляется с башни у лагеря {object:3202}; он причаливает у главных ворот ({zone:1454}).",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Волки: {npc:3362}, рядом: {npc:4752}.",
		["Woodpaw battle map"] = "Тактическая карта Древолапов",
		["Woodpaw north camp"] = "Северный лагерь Древолапов",
		["Zeppelin to {object:3202}"] = "Дирижабль: {object:3202}",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["Zeppelin tower"] = "Башня дирижаблей",
		["for the {zone:1425}, around level 48"] = "для края {zone:1425}, примерно на 48-м уровне",
		["for {zone:1454}, around level 45"] = "для города {zone:1454}, примерно на 45-м уровне",
		["the {object:150075} in the square"] = "{object:150075} на площади",
		["water pouches in your bags"] = "бурдюки с водой в сумках",
		["{npc:3690}, riding trainer"] = "{npc:3690}, учитель верховой езды",
		["{npc:4752}, riding trainer"] = "{npc:4752}, учитель верховой езды",
		["{npc:4773}, riding trainer"] = "{npc:4773}, учитель верховой езды",
		["{npc:7953}, riding trainer"] = "{npc:7953}, учитель верховой езды",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: для города {zone:1454}, примерно на 45-м уровне",
		["{npc:8579}: the screechers live in {zone:1444}"] = "{npc:8579}: крикуны живут здесь: {zone:1444}",
		["{quest:2863}: one hour from now"] = "{quest:2863}: в течение часа",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Dragon caves"] = "Драконьи пещеры",
		["Fly to {object:3202}"] = "Летите сюда: {object:3202}",
		["Forest walkers"] = "Лесные древни",
		["Frayfeather hippogryphs"] = "Блеклоперые гиппогрифы",
		["Monstrous Crawlers"] = "Чудовищные крабы",
		["Murlocs of the Misty Reed"] = "Мурлоки Тростникового берега",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "На северо-запад по дороге, у пещер в холмах живут йети Бешеного оврага. С любого может также упасть {quest:7738} – это начинает отдельное задание.",
		["Northspring harpies"] = "Гарпии Студеных Ключей",
		["Onyxia's eggs"] = "Яйца Ониксии",
		["Rage Scar yetis"] = "Йети Бешеного оврага",
		["Ride back north to Brackenwall."] = "Возвращайтесь на север в Гиблотопь.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Езжайте на запад по дороге; свиток лежит у кромки воды на дальнем западе болота.",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "Морские элементали и морские валы бродят по берегу у причала. Сначала уменьшите великанов предметом {item:18904}: уменьшенные, они теряют силу элиты. Береговые странники бродят в воде; сухопутные бродяги и скальные великаны – на холмах дальше к северу.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "К югу от долины на склонах гнездятся блеклоперые гиппогрифы; почти с каждого падают сухожилия и металлические осколки.",
		["Sprite darters and forest walkers"] = "Летучие хамелеоны и лесные древни",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Болотные мурлоки живут на берегу к югу от лагеря; чернильщики – вдоль берега к востоку, а трупоеды – дальше к западу, у хижин на западном берегу.",
		["The Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see on the way south."] = "Чудовищные крабы редко встречаются на пляжах восточного побережья: убивайте каждого, кого встретите по пути на юг.",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "Гарпии из стаи Студеных Ключей гнездятся на хребтах на дальнем северо-западе. Они 48-50 уровня, на несколько уровней выше вас: призывательницы ветров лечат – убивайте их первыми и выманивайте по одной.",
		["The same murlocs again, plus the Oracles, who stay near the huts on the western shore."] = "Снова те же мурлоки, плюс оракулы – они держатся у хижин на западном берегу.",
		["The small Horde post on the southern shore."] = "Небольшой лагерь Орды на южном берегу.",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "Летучие хамелеоны порхают над рощей чуть к западу от лагеря; у них – {item:9589}; у бродячих лесных древней чуть дальше к западу – расколотые бревна.",
		["The zeppelin to {zone:1454} leaves from the tower beside {object:3202}; it lands just north-east of {zone:1454}'s main gate."] = "Дирижабль ({zone:1454}) отправляется с башни у лагеря {object:3202}; он причаливает чуть к северо-востоку от главных ворот ({zone:1454}).",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["Zeppelin tower"] = "Башня дирижаблей",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "для персонажа {npc:5598} ({zone:1425}), примерно на 48-м уровне",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "для предмета {object:2555} ({zone:1445}), позже в этом руководстве",
		["for the {zone:1425} owlbeasts, around level 48"] = "для совухов ({zone:1425}), примерно на 48-м уровне",
		["the {object:2555}"] = "{object:2555}",
		["{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "{npc:4500} – элита: лучше собрать группу. Бейте его, пока он не сдастся, затем доложите персонажу {npc:4501}.",
		["{npc:7875}: for {npc:7010} in {zone:1454}, around level 50"] = "{npc:7875}: для персонажа {npc:7010} ({zone:1454}), примерно на 50-м уровне",
		["{object:172958}, then the {object:172960} and the {object:172961}."] = "{object:172958}, затем {object:172960} и {object:172961}.",
		["{quest:7738}, a rare drop"] = "{quest:7738}, редкая добыча",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Dark Iron Lookouts"] = "Наблюдатели из клана Черного Железа",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive."] = "Дальше к югу обозревательное устройство младшего геодезиста лежит у входа в улей сентипааров.",
		["Greater Lava Spiders"] = "Опаляющие лавовые пауки",
		["Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it."] = "Тяжелые боевые големы патрулируют Котлован под Калараном – с них падает масло; с элементалей магмы и пылающих элементалей среди них падают сердца. Надсмотрщики и поработители из клана Черного Железа гонят рабов по тропам; с поработителя может упасть {item:11818}: сохраните его.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Для следующей просьбы нужен предмет {item:10552} с элитных культистов: не берите ее.",
		["OOX-17/TN"] = "КПХ-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Только с предметом {item:11818}: назад на восток к раскопкам ({object:173265}).",
		["Scrimshank's gear"] = "Устройство Холстомера",
		["South down the road again."] = "Снова на юг по дороге.",
		["South-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp."] = "К юго-востоку от Прибамбасска в дюнах стоят лагерем бандиты Скитальцев Пустыни; {npc:7847} – в восточном лагере.",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Наблюдатели из клана Черного Железа стоят на хребтах у сторожевых башен к югу от Котлована; {item:18960} – примерно у каждого десятого.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Кузнецы из клана Черного Железа работают у горнов в центре Котлована; у половины – {item:10551}, у каждого десятого – {item:18959}. Кинжалы есть также у рабов, поработителей и надсмотрщиков.",
		["The Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge."] = "Опаляющие лавовые пауки бродят по плато и лавовым озерам на юго-западе ущелья.",
		["The Steamsmiths' furnaces"] = "Горны кузнецов",
		["The {object:179827} board"] = "Доска: {object:179827}",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "К западу от Прибамбасска используйте предмет {item:8584} у водопоя в лагере троллей.",
		["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one."] = "К западу от лагеря долину заполняют кактусовые существа; росяная железа – только у собирателей росы. С большинства монстров ({zone:1446}) изредка падает аварийный маяк КПХ-17/TN: сохраните его, если выпадет.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts."] = "К западу насекомые-сентипаары роятся у своих ульев; части тел падают с любого.",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526} растет здесь: {zone:1425}, примерно на 48-м уровне",
		["the {object:150075} in the square"] = "{object:150075} на площади",
		["the {object:173265}"] = "{object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}, редкая добыча",
		["{item:8623}, a rare drop"] = "{item:8623}, редкая добыча",
		["{npc:5955}'s escort"] = "Сопровождение: {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, рядом с распорядителем полетов",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["East of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south."] = "К востоку от дороги на склонах пасутся пеплогривые кабаны и хрюггеры, рядом – краснокаменные василиски. Держитесь подальше от зловепрей 52-го уровня дальше к югу.",
		["East of the village, the violet flower grows in the hills."] = "К востоку от деревни на холмах растет фиолетовый цветок.",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Следуйте по дорогам на восток через {zone:1425} к деревне троллей на восточном побережье.",
		["Grind to 48"] = "Набейте 48-й уровень",
		["Highvale"] = "Высокодолье",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "К северу вдоль берега на маленьком острове – корзинка для пикника ({npc:14731}); ее охраняет {npc:14748}.",
		["OOX-09/HL"] = "OOX-09/HL",
		["Only if you are not level 48 yet."] = "Только если у вас еще нет 48-го уровня.",
		["Ride back north to the bloodmages."] = "Возвращайтесь на север к волшебникам крови.",
		["Saltwater Snapjaws"] = "Морские хрустогрызы",
		["Silvermane Howlers"] = "Среброгривые ревуны",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "К югу от поселения тролли племени Сухокожих занимают свои деревни. Череп есть у каждого: собрав двадцать, используйте предмет {item:15002}, чтобы сделать пику с тролльими черепами, затем установите ее в деревне.",
		["South-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "К юго-западу среброгривые ревуны бродят по холмам к востоку от деревень Сухокожих.",
		["The Vilebranch temples"] = "Храмы Порочной Ветви",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "Большие черепахи ползают по пляжам к северу от деревни. Бутылки портвейна ({npc:2491}) тоже лежат на этих пляжах, но его задания нет в маршруте. С черепахи изредка падает аварийный маяк OOX-09/HL: сохраните его.",
		["The bloodmages"] = "Волшебники крови",
		["The central hills"] = "Центральные холмы",
		["The eastern slopes"] = "Восточные склоны",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills."] = "Для пяти заданий нужны одни и те же части: соберите все за один проход. К западу от дороги на холмах живут грифы ({npc:5982}), голодные хохотуны, скорпоки-острожалы и василиски-смертеглазы.",
		["The northern beasts"] = "Северные звери",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Следующие задания снова требуют те же части ради предмета с усилением и не дают опыта: не берите их.",
		["Vilebranch soothsayers"] = "Ворожеи Порочной Ветви",
		["Vulture hills"] = "Холмы грифов",
		["for {npc:6986} in {zone:1454}, around level 50"] = "для персонажа {npc:6986} ({zone:1454}), примерно на 50-м уровне",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "для персонажа {npc:7825} ({zone:1458}), примерно на 50-м уровне",
		["grind on {npc:5982} at the northern hills, {zone:1419}"] = "бейте монстров {npc:5982} на северных холмах, {zone:1419}",
		["{item:8704}, a rare drop"] = "{item:8704}, редкая добыча",
		["{npc:14731}'s lunch"] = "Обед: {npc:14731}",
		["{npc:6741}: for {zone:1456}, around level 50"] = "{npc:6741}: для города {zone:1456}, примерно на 50-м уровне",
		["{npc:7801}'s camp"] = "Лагерь {npc:7801}",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}, {object:36126}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "Обратно на северо-восток: {npc:8420}.",
		["Back to {object:3202}"] = "Вернитесь: {object:3202}",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "Идите по дороге на юг; василиски греются на камнях к востоку от нее посреди джунглей. Осколки падают часто.",
		["Frayfeather Hippogryphs"] = "Блеклоперые гиппогрифы",
		["Highborne and Haldarr satyrs"] = "Высокорожденные и сатиры из племени Халдарр",
		["Ironjaw Basilisks"] = "Железозубые василиски",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "Сохраните доставки для {npc:4046}, NPC {npc:8659} и {npc:6522}: позже вы будете проезжать {zone:1456}, {zone:1454} и {zone:1458}.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Сохраните {quest:3444}: сундук {npc:7771} откроется при следующем визите.",
		["Only once all three robots are home"] = "Только когда все три робота дома",
		["Ride into {zone:1447}"] = "Въезжайте: {zone:1447}",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "Езжайте на юго-запад к руинам. Четыре скрижали лежат среди руин под охраной наг из клана Бича Злобы; у любой сирены или мирмидона может оказаться руна ({npc:8420}).",
		["Sea elementals"] = "Морские элементали",
		["Sprite Darters"] = "Летучие хамелеоны",
		["Take the zeppelin back to {zone:1454}."] = "Летите на дирижабле обратно: {zone:1454}.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Призраки высокорожденных бродят по руинам чуть севернее святилища; сатиры из племени Халдарр стоят лагерем немного дальше на север.",
		["The Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "Сухопутные бродяги и скальные великаны бродят по холмам к северу от причала. Сначала ударьте каждого предметом {item:18904}: уменьшенные, они больше не элита. С каждого уменьшенного великана падает осадок; используйте на его теле и сосуд для уменьшенных горных великанов.",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock."] = "Морские элементали и морские валы плещутся у берега вокруг причала.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "Лагерь эльфов крови — чуть южнее: {npc:8420}. Четыре предмета его снаряжения лежат в ящиках вокруг лагеря.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Лесные дракончики порхают в лесу чуть западнее лагеря. Используйте сосуд на каждом убитом.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Гиппогрифы гнездятся на холмах к юго-западу от лагеря. Убейте одного, затем используйте сосуд для уменьшенных гиппогрифов на его теле.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Древни бродят по лесным дорогам между лагерем и центром зоны {zone:1444}; их немного, так что ищите вдоль троп.",
		["The {object:2076} beside {npc:2519}"] = "{object:2076} рядом с NPC {npc:2519}",
		["To {object:3202}"] = "Путь: {object:3202}",
		["Undamaged Hippogryph Feathers"] = "Неповрежденные перья гиппогрифа",
		["Wandering Forest Walkers"] = "Бродячие лесные древни",
		["Zapped giants"] = "Уменьшенные великаны",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}, Волок",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}: медведи — в зоне {zone:1448}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825} стоит здесь: {object:36082}.",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "Смола ({npc:7876}) и образцы Пестычинса — из зоны {zone:1449}.",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, рядом с распорядителем ветрокрылов",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}, на восточном краю лагеря: опыта нет, только телепорт в башню Азшары",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761} собирается в следующем гайде; плату {npc:4046} позже отнесете: {npc:8587}.",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Black Broodlings"] = "Детеныши черного дракона",
		["Bloodpetal Flayers"] = "Кровоцветы-живодеры",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Пересеките юг кратера к пилону на западных скалах.",
		["Darrowshire Spirits"] = "Духи Дарроушира",
		["Eastern Pylon"] = "Восточный пилон",
		["Escort {npc:9999}"] = "Сопровождение: {npc:9999}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Идите вдоль скал на юг сюда: {quest:3821} – холм огров клана Огненного Чрева. Останки ({npc:9136}) лежат у подножия.",
		["Free Darrowshire Spirits: talk to them"] = "Освободите духов Дарроушира: поговорите с ними",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "Отсюда собирайте все кристаллы силы (синие, зеленые, красные, желтые) и все кучи земли ({quest:3761}) по пути: всего 25 земли – 20 для Хамуула и 5 для Пестычинса.",
		["Gorillas"] = "Гориллы",
		["Into the {zone:1427}"] = "В край {zone:1427}",
		["Into {zone:1449}"] = "В край {zone:1449}",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "Сохраните приманку: {npc:9684} – 56-го уровня, а второй круг проходит мимо его логова.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Сохраните задание {quest:4147} ({npc:9118}) и письмо ({npc:8737}) для следующих руководств.",
		["Lar'korwi Mates"] = "Самки Лар'корви",
		["Lashers and Threshers"] = "Хлыстуны и крепкозубы",
		["North of Torwa, a dead Threshadon lies by the water."] = "К северу от Торвы у воды лежит мертвый жесткозуб.",
		["Northern Pylon"] = "Северный пилон",
		["Out of the refuge"] = "Снаружи лагеря",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "Следующее задание Пестычинса требует убить элитного босса ({npc:10041}). Пропустите.",
		["Power Crystals and soil"] = "Кристаллы силы и земля",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Спуститесь по восточной части кратера к пилону на восточных скалах.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Езжайте на север вдоль восточной части. Джунгли полны кровоцветов-хлыстунов и крепкозубов.",
		["Ride south-west along the western cliffs. {npc:9167} fly over the west side, and Bloodpetal Trappers grow in the same jungle."] = "Езжайте на юго-запад вдоль западных скал. Над западной частью летают монстры {npc:9167}, а в тех же джунглях растут кровоцветы-звероловы.",
		["Ride west to the dig site. {npc:7039} golems (53) stomp around it and drop the shards often; the {quest:4296} stands in its middle among the Thaurissan dwarves. Copy it."] = "Езжайте на запад к раскопкам. Големы ({npc:7039}, 53) топчутся вокруг, осколки с них падают часто; табличка ({quest:4296}) стоит в центре среди дворфов Тауриссана. Скопируйте ее.",
		["South of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales {npc:9998} wants. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon."] = "К югу от горячих источников пасутся стегодоны; кости динозавров падают с них или лежат на земле; у деметродонов рядом – чешуя для персонажа {npc:9998}. Равазавры охотятся стаями на юго-западе: их когти – для персонажа {npc:8659}, а иногда с них падает истрепанный дневник (редкая добыча: берите задание, только если он выпадет). Избегайте Граффа – стегодона 57-го уровня.",
		["Stegodons and ravasaurs"] = "Стегодоны и равазавры",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "Возьмите {object:176092} из ящика рядом с Деррингтоном для задания {quest:5096} – выполните его на обратном пути. Наденьте {quest:5401}: камни Плети падают, только пока он надет.",
		["Termite mounds"] = "Термитники",
		["Thaurissan dig site"] = "Раскопки Тауриссана",
		["The Gorishi hive"] = "Улей Гориши",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Самки Лар'корви бродят по джунглям к северо-западу от {npc:9619}.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "Голова куклы и две ее половины лежат в домах вокруг {npc:10926}; соедините их в сумках.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "Ящик экспедиции стоит в заброшенном лагере в восточных джунглях.",
		["The expedition's lost equipment lies in the south-west jungle."] = "Потерянное снаряжение экспедиции лежит в юго-западных джунглях.",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "Гориллы живут на северо-восточном плато. Не заходите в самую дальнюю пещеру: там живет {npc:9622}.",
		["The next guide starts here, at the chapel's flight master."] = "Следующее руководство начинается здесь, у распорядителя полетов часовни.",
		["The pylon stands on the slope east of the refuge."] = "Пилон стоит на склоне к востоку от лагеря.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "Плот лежит на берегу юго-восточного озера; небольшой рюкзак – в воде рядом.",
		["The silithid hive fills the south of the crater. Gorishi wasps and workers drop the scent gland; use the Scraping Vial on the egg mass inside the first chamber. The Hive Queen at the bottom is an elite boss: stay out of her chamber. {npc:9166} nest on the cliffs above the hive; their scales are for {npc:9998}."] = "Улей силитидов занимает юг кратера. С ос и рабочих из улья Гориши падает пахучая железа; используйте склянку для соскобов на кладке яиц в первой камере. Матка улья внизу – элитный босс: не заходите в ее камеру. Монстры {npc:9166} гнездятся на скалах над ульем; их чешуя – для персонажа {npc:9998}.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "Смоляные ямы – чуть к югу от лагеря. {item:11834} падает со смоляных тварей, скрытней и ползунов.",
		["The wooden sign beside {npc:9997}"] = "Деревянная табличка рядом с {npc:9997}",
		["Use the Mangled Journal to start it"] = "Используйте истрепанный дневник, чтобы начать задание",
		["Western Pylon"] = "Западный пилон",
		["Western jungle"] = "Западные джунгли",
		["{item:11116}, a rare drop"] = "{item:11116}, редкая добыча",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302} отправляет вас к персонажу {npc:9298} ({zone:1452}): сохраните задание.",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, рядом с распорядителем полетов",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}, {object:36073}",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, Район Фармацевтов: склянки наполните позже ({zone:1447})",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}, в глубине пещеры",
		["{npc:9618}, just outside"] = "{npc:9618}, сразу снаружи",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} стоит лагерем в юго-восточном углу кратера.",
		["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "Теперь {npc:9619} просит шкуру ({npc:9622}) из северо-восточной пещеры: пропустите.",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "Затем {npc:9623} просит предмет {item:10561} (профессия {skill:202}). Пропустите, если его у вас нет.",
		["{npc:9623}, the robot on the plateau"] = "{npc:9623}, робот на плато",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "Логово ({npc:9684}) – чуть к югу от пилона. Используйте там приманку {npc:9619}; {npc:9684} – 56-го уровня и бьет сильно, начинайте с полным здоровьем.",
		["{npc:9998}, at the entrance"] = "{npc:9998}, у входа",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, у входа в лагерь",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999} сидит на хребте, заблудившийся и обессиленный.",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} бродит по пещерам и штольням ({quest:3821}); если его нет, бейте огров у входов, пока он не вернется.",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "Сторожевые башни Деррингтона, котел Вандис и бочка {npc:11615} – в следующий визит: сохраните эти задания.",
		["Diseased Grizzlies"] = "Болезненные гризли",
		["Diseased Wolves"] = "Больные волки",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "К востоку от Заставы Отравленной Крови – долина с кратерами, где бродят энтропические звери и ужасы. Убейте по два каждого, затем подойдите к каждому из трех кратеров с водой Скверны.",
		["Jadefire moonwell"] = "Лунный колодец Нефритового Пламени",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "Сохраните ветвь: {npc:5770} – здесь: {zone:1456}.",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "Сохраните задание {quest:5158}: {npc:5901} – здесь: {zone:1413}.",
		["Keep {quest:8465} for {zone:1452}."] = "Сохраните задание {quest:8465} для края {zone:1452}.",
		["Northern crater"] = "Северный кратер",
		["Only with 5 Deadwood Headdress Feathers"] = "Только с 5 перьями ({item:21377})",
		["Radley and Durgen"] = "Рэдли и Дурген",
		["Ride back south-east to the Sanctuary."] = "Возвращайтесь на юго-восток в Изумрудное святилище.",
		["Ride north up the road again."] = "Снова езжайте на север по дороге.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Езжайте на северо-запад в Андорал. {npc:10667} ждет в разрушенной таверне в западной части города; скелеты внутри 54-57 уровня, держитесь окраин.",
		["Ride the road south through {zone:1448} to the Sanctuary."] = "Езжайте по дороге на юг через край {zone:1448} к святилищу.",
		["Scarlet Crusade"] = "Алый орден",
		["Scarlet forward camp"] = "Передовой лагерь Алого ордена",
		["Southern crater"] = "Южный кратер",
		["Take the kitten to the same moonwell and release it there; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "Отнесите котенка к тому же лунному колодцу и выпустите его; когда он превратится в монстра {npc:10042}, приведите его к {npc:9996} и щелкните по нему, чтобы передать.",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "Летопись лежит среди затхлых фолиантов ({object:176150}) в ратуше Андорала; открывайте их, пока не найдете нужный.",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "Деревня фурболгов Мертвого Леса чуть к западу от туннеля. {npc:9462} (56) стоит среди них. {npc:11557}, дружелюбный фурболг, сидит в северной части деревни.",
		["The Jadefire moonwell"] = "Лунный колодец Нефритового Пламени",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "Дневник лежит в доме, шкаф стоит внутри, а уборная – за домом. Ключ от уборной у монстра {npc:10816}; {npc:10836} выходит, когда вы открываете уборную, – у него ключ от шкафа.",
		["The druids' camp is just past the border."] = "Лагерь друидов – сразу за границей.",
		["To {zone:1448}"] = "В край {zone:1448}",
		["Western crater"] = "Западный кратер",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}: совухи – здесь: {zone:1452}",
		["{npc:10840}, at the graveyard's south end"] = "{npc:10840}, в южной части кладбища",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, на южном краю лагеря",
		["{npc:11557}: keep 30 {quest:6031} for him; he trades only at Neutral with the Timbermaw"] = "{npc:11557}: сохраните для него 30 шт. ({quest:6031}); он торгует только при нейтральном отношении Древобрюхов",
		["{npc:11558}, at the tunnel mouth"] = "{npc:11558}, у входа в туннель",
		["{npc:11610}'s last task needs level 53. The Scarlet Knights and Magi (54-55) working the lumber camp just south-west of her are the closest camp."] = "Последнее задание {npc:11610} требует 53-го уровня. Рыцари и волхвы из Алого ордена (54-55) на лесопилке чуть к юго-западу от нее – ближайшее место.",
		["{npc:1855}'s hunts are in the {zone:1423}: keep them for later."] = "Охоты от {npc:1855} – здесь: {zone:1423}: сохраните их на потом.",
		["{npc:9529}, just west of the camp"] = "{npc:9529}, чуть к западу от лагеря",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, в западной части святилища",
		["{npc:9996}'s kitten"] = "Котенок {npc:9996}",
